import { UndoRedo, Button } from "march/ui"

// emoji dizisi: her emoji bir adım; UndoRedo'ya küçük bir geçmiş (history) verilir, ipucu adımı adıyla söyler
// ("Geri al: 🌵"); geçmiş iki sinyalden ibaret: yapılanlar ve geri alınanlar
const palette = ["🌵", "🐙", "🍕", "🚀", "🌈"]

export function EmojiPainter() {
  let $past: string[] = []
  let $future: string[] = []
  const history = {
    canUndo: () => $past.length > 0,
    canRedo: () => $future.length > 0,
    undo: () => { const last = $past[$past.length - 1]; $past = $past.slice(0, -1); $future = [last, ...$future] },
    redo: () => { const [next, ...rest] = $future; $future = rest; $past = [...$past, next] },
    past: () => [...$past].reverse(),
    future: () => $future,
  }
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "center"], gap: 1 }}>
      {palette.map((e) => <Button variant="ghost" on:click={() => { $past = [...$past, e]; $future = [] }}>{e}</Button>)}
      <UndoRedo history={history} size="sm" />
    </div>
    <div sx={{ text: "2xl" }}>{$past.length ? $past.join("") : "Bir emojiye bas"}</div>
  </div>
}

import { UndoRedo, Card, Button, IconButton } from "march/ui"
import { check, plus } from "march/icons"

// bir görev listesinin araç çubuğu: ekle ve tamamla adımları geri alınabilir; UndoRedo dört prop'la sürülür
// (canUndo, canRedo, onUndo, onRedo) ve steps her düğmenin ipucuna adımın adını yazar
interface Step { label: string; before: string[]; after: string[] }

export function TaskBoard() {
  let $tasks = ["Sunumu bitir", "Faturayı öde", "Spor salonu"]
  let $done: Step[] = []
  let $undone: Step[] = []
  let $n = 1
  const run = (label: string, next: string[]) => { $done = [...$done, { label, before: $tasks, after: next }]; $undone = []; $tasks = next }
  const undo = () => { const s = $done[$done.length - 1]; $done = $done.slice(0, -1); $undone = [s, ...$undone]; $tasks = s.before }
  const redo = () => { const s = $undone[0]; $undone = $undone.slice(1); $done = [...$done, s]; $tasks = s.after }
  return <Card title="Bugün" actions={<UndoRedo canUndo={$done.length > 0} canRedo={$undone.length > 0} onUndo={undo} onRedo={redo}
    steps={{ undo: $done[$done.length - 1]?.label, redo: $undone[0]?.label }} labels={{ group: "Görev geçmişi" }} size="sm" />}>
    <div sx={{ flex: "col", gap: 1 }}>
      {$tasks.map((t) => <div sx={{ flex: ["row", "between", "center"] }}>
        <span>{t}</span>
        <IconButton icon={check} label={`${t}: tamamlandı`} size="sm" on:click={() => run(`Tamamla: ${t}`, $tasks.filter((x) => x !== t))} />
      </div>)}
      {$tasks.length ? null : <span sx={{ color: "muted" }}>Hepsi bitti 🎉</span>}
      <Button size="sm" variant="ghost" icon={plus} on:click={() => { const name = `Yeni görev ${$n}`; $n += 1; run(`Ekle: ${name}`, [...$tasks, name]) }}>Görev ekle</Button>
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { UndoRedoLab } from "./UndoRedoLab.tsx"

// UndoRedoLab'in testleri: kaydedince Testler sekmesinde çalışır
test("+1'den sonra Vazgeç adımı adıyla söyler, geri alınca Yeniden açılır", async () => {
  const s = renderTest(() => <UndoRedoLab />)
  expect((s.get(".lab-undo") as HTMLButtonElement).disabled).toBe(true)
  await s.click("+1")
  expect(s.get(".lab-undo")?.getAttribute("aria-label")).toBe("Vazgeç: +1")
  await s.click("Vazgeç: +1")
  expect(s.get(".lab-count")?.textContent).toBe("0")
  expect((s.get(".lab-redo") as HTMLButtonElement).disabled).toBe(false)
  expect(s.get(".lab-redo")?.getAttribute("aria-label")).toBe("Yeniden: +1")
})

test("grubun adı labels.group; ipucunda adım ve kendi kısayolu", async () => {
  const s = renderTest(() => <UndoRedoLab />)
  expect(s.find("Sayaç geçmişi")?.getAttribute("role")).toBe("group")
  await s.click("×2")
  const title = s.get(".lab-undo")?.getAttribute("title") ?? ""
  expect(title).toContain("Vazgeç: ×2")
  expect(title).toContain("Z")
})

test("actions sırası; steps={false} ve shortcuts={false}: ipucu yalnız ad", async () => {
  const s = renderTest(() => <UndoRedoLab />)
  expect(s.get(".lab-props button")?.classList.contains("m-undo-redo-redo")).toBe(true)
  await s.click("Bayrağı dik")
  const undo = s.get(".lab-props .m-undo-redo-undo")
  expect((undo as HTMLButtonElement).disabled).toBe(false)
  expect(undo?.getAttribute("title")).toBe(undo?.getAttribute("aria-label"))
})

test("Kilitle: disabled düğmeleri kapatır; actions={[\"undo\"]} tek düğme çizer", async () => {
  const s = renderTest(() => <UndoRedoLab />)
  await s.click("+1")
  await s.click("Kilitle")
  expect((s.get(".lab-undo") as HTMLButtonElement).disabled).toBe(true)
  expect(s.all(".lab-only button").length).toBe(1)
})
